<?php
declare(strict_types=1);
$user = current_user();
$stmt = db()->query('SELECT a.ad_id,a.title,a.description,a.price,a.status,a.published_at,u.display_name AS author_name,c.name AS category_name,ci.name AS city_name FROM ads a JOIN users u ON u.user_id=a.author_id JOIN categories c ON c.category_id=a.category_id LEFT JOIN cities ci ON ci.city_id=a.city_id WHERE a.status = \'active\' ORDER BY a.published_at DESC');
$ads = $stmt->fetchAll();
?>
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Объявления</title><link rel="stylesheet" href="../assets/css/auth.css"></head><body><main class="site-shell"><header class="topbar"><a class="brand" href="<?= e(route_url()) ?>">Доска объявлений</a><nav><a href="<?= e(route_url('categories')) ?>">Категории</a><a href="<?= e(route_url('cities')) ?>">Города</a><?php if($user): ?><a href="<?= e(route_url('cabinet')) ?>">Кабинет</a><?php else: ?><a href="<?= e(route_url('login')) ?>">Войти</a><?php endif; ?></nav></header><section class="content-card"><span class="eyebrow">Данные из БД</span><h1>Список объявлений</h1><p class="subtitle">Показываются только объявления со статусом active.</p><div class="entity-grid"><?php foreach($ads as $ad): ?><article class="entity-card"><div class="entity-top"><span class="tag"><?= e($ad['category_name']) ?></span><span><?= e($ad['city_name'] ?? 'Не указан') ?></span></div><h2><?= e($ad['title']) ?></h2><p><?= e($ad['description']) ?></p><strong class="price"><?= e((string)$ad['price']) ?> ₽</strong><small>Автор: <?= e($ad['author_name']) ?></small></article><?php endforeach; ?></div><?php if(!$ads): ?><p>Активных объявлений нет.</p><?php endif; ?></section></main></body></html>
